        </div>
        <div style={{ textAlign:"right" }}>
          <div style={{ color:"white", fontSize:12, marginBottom:4 }}>Usuario: {user?.email}</div>
          <div style={{ color:"#F5A623", fontSize:11, marginBottom:8 }}>👑 Usuario Master</div>
          <button
