    console.log("📋 1. VERIFICANDO CONFIGURACIÓN");
    const defaultUrl = process.env.REACT_APP_SUPABASE_URL || "";
    const defaultKey = process.env.REACT_APP_SUPABASE_ANON_KEY || "";

    let url = defaultUrl;
    let key = defaultKey;

