  profile_exists BOOLEAN;
BEGIN
  -- Obtener el ID del usuario por email
  SELECT id INTO user_id 
  FROM auth.users 
  WHERE email = p_email;

  IF user_id IS NULL THEN
    RETURN 'ERROR: Usuario no encontrado en auth.users';
  END IF;

  -- Verificar si el perfil ya existe
