            </button>
            <button
              onClick={() => setBulkType("fixed")}
              style={{
                flex:1,
                padding:10,
                borderRadius:8,
                border: bulkType === "fixed" ? "2px solid #C41E3A" : "1px solid #E5E7EB",
                background: bulkType === "fixed" ? "#C41E3A" : "white",
                color: bulkType === "fixed" ? "white" : "#374151",
                fontWeight:600,
                cursor:"pointer",
                fontSize:13
              }}
