  const getNextDeliveryDate = (zone) => {
    const now = new Date();
    const currentHour = now.getHours();
    const currentDay = now.getDay(); // 0 = Domingo, 1 = Lunes, etc.

    const zoneDays = {
      1: [1, 2], // Lunes y Martes
      2: [3, 4], // Miércoles y Jueves
      3: [5, 6]  // Viernes y Sábado
    };

    const zoneLocalities = {
      1: "Escobar, Tigre, San Fernando, Vicente López, Capital Federal",
      2: "Pilar, Malvinas Argentinas, San Miguel, Hurlingham, San Martín, Tres de Febrero",
      3: "José C. Paz, Moreno, Merlo, Morón, La Matanza y zonas aledañas"
    };

    const days = zoneDays[zone];
    if (!days) return null;

    // Si ya pasó la hora de corte, descartar el día de hoy
    let searchDay = currentDay;
    if (currentHour >= shippingCutoffHour) {
      searchDay = currentDay + 1;
      if (searchDay > 6) searchDay = 0; // Volver a Domingo
    }

    // Buscar el próximo día disponible
    let deliveryDate = new Date(now);
    let daysToAdd = 0;
    let found = false;

    for (let i = 0; i < 7; i++) {
      const checkDay = (searchDay + i) % 7;
      if (days.includes(checkDay)) {
        daysToAdd = i;
        found = true;
        break;
      }
    }

    deliveryDate.setDate(deliveryDate.getDate() + daysToAdd);

    const dayNames = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
    const dayName = dayNames[deliveryDate.getDay()];

    return {
      date: deliveryDate,
      formatted: `${dayName} ${deliveryDate.getDate()}/${deliveryDate.getMonth() + 1}`,
      localities: zoneLocalities[zone]
    };
  };

