  if (!p) { 
    console.error("Se intentó renderizar un ProductCard sin datos"); 
    return null; 
  }

  // PARCHE DE SEGURIDAD TOTAL: Desestructuración con valores por defecto
  const { 
    category = 'Sin categoría', 
    name = 'Producto sin nombre', 
    price = 0, 
    image_url = '', 
    bulkInfo = '',
    description = '',
    retail_price = 0,
    show_retail_price = false,
    badges = [],
    min_boxes = 1
