  // PARCHE DE SEGURIDAD TOTAL: Log de depuración
  console.log('Renderizando producto:', p?.id || 'ID NULO');

  const color = CAT_COLOR[category] || "#C41E3A";
  const emoji = CAT_EMOJI[category] || "🍖";

