// PAGINATION COMPONENT (CAMBIO 8)
// ═══════════════════════════════════════════════════════

function Pagination({ currentPage, totalPages, setCurrentPage }) {
  if (totalPages <= 1) return null;

  const getPageNumbers = () => {
    const pages = [];
    const maxVisible = 5;

    if (totalPages <= maxVisible) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      if (currentPage <= 3) {
        pages.push(1, 2, 3, 4, '...', totalPages);
      } else if (currentPage >= totalPages - 2) {
        pages.push(1, '...', totalPages - 3, totalPages - 2, totalPages - 1, totalPages);
      } else {
        pages.push(1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages);
      }
    }

    return pages;
  };

  return (
    <div style={{ display:"flex", justifyContent:"center", alignItems:"center", gap:8, marginTop:24, padding:"16px 0" }}>
      <button
        onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
        disabled={currentPage === 1}
        style={{
          padding:"8px 16px",
          background:currentPage === 1 ? "#F3F4F6" : "white",
          color:currentPage === 1 ? "#9CA3AF" : "#374151",
          border:"1px solid #E5E7EB",
          borderRadius:8,
          fontSize:13,
          fontWeight:600,
          cursor:currentPage === 1 ? "not-allowed" : "pointer",
          fontFamily:"'Poppins',sans-serif",
          opacity:currentPage === 1 ? 0.5 : 1
        }}
      >
        ← Anterior
      </button>

      {getPageNumbers().map((page, idx) => (
        page === '...' ? (
          <span key={idx} style={{ padding:"8px 12px", color:"#9CA3AF" }}>...</span>
        ) : (
          <button
            key={idx}
            onClick={() => setCurrentPage(page)}
            style={{
              padding:"8px 14px",
              background:currentPage === page ? "#C41E3A" : "white",
              color:currentPage === page ? "white" : "#374151",
              border:currentPage === page ? "none" : "1px solid #E5E7EB",
              borderRadius:8,
              fontSize:13,
              fontWeight:600,
              cursor:"pointer",
              fontFamily:"'Poppins',sans-serif"
            }}
          >
            {page}
          </button>
        )
      ))}

      <button
        onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
        disabled={currentPage === totalPages}
        style={{
          padding:"8px 16px",
          background:currentPage === totalPages ? "#F3F4F6" : "white",
          color:currentPage === totalPages ? "#9CA3AF" : "#374151",
          border:"1px solid #E5E7EB",
          borderRadius:8,
          fontSize:13,
          fontWeight:600,
          cursor:currentPage === totalPages ? "not-allowed" : "pointer",
          fontFamily:"'Poppins',sans-serif",
          opacity:currentPage === totalPages ? 0.5 : 1
        }}
      >
        Siguiente →
      </button>
    </div>
  );
}

