            </div>
            <div style={{ padding:16, background:"white", border:"1px solid #E5E7EB", borderRadius:8 }}>
              <div style={{ fontWeight:600, marginBottom:8, color:"#C41E3A" }}>Zona 2 - Miércoles y Jueves</div>
              <div style={{ fontSize:13, color:"#6B7280" }}>Pilar, Malvinas Argentinas, San Miguel, Hurlingham, San Martín, Tres de Febrero</div>
            </div>
            <div style={{ padding:16, background:"white", border:"1px solid #E5E7EB", borderRadius:8 }}>
              <div style={{ fontWeight:600, marginBottom:8, color:"#C41E3A" }}>Zona 3 - Viernes y Sábado</div>
              <div style={{ fontSize:13, color:"#6B7280" }}>José C. Paz, Moreno, Merlo, Morón, La Matanza y zonas aledañas</div>
            </div>
          </div>

          <div style={{ marginTop:24, padding:16, background:"#F9FAFB", borderRadius:12, border:"1px solid #E5E7EB" }}>
            <div style={{ fontWeight:700, color:"#374151", marginBottom:12, fontSize:14 }}>Productos por página</div>
            <div style={{ display:"flex", alignItems:"center", gap:12 }}>
              <input 
                type="number" 
                value={productsPerPage}
                onChange={(e) => {
                  const val = parseInt(e.target.value);
                  if (val >= 6 && val <= 24) {
                    setProductsPerPage(val);
                    localStorage.setItem("products_per_page", val);
                  }
                }}
                min="6"
                max="24"
                style={{ padding:"10px", borderRadius:8, border:"1px solid #E5E7EB", fontSize:14, width:80 }}
              />
              <span style={{ fontSize:14, color:"#6B7280" }}>productos por página en la tienda</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

