                }} 
                style={{...input, marginBottom:10}} 
                placeholder="https://ejemplo.com/imagen.jpg (opcional)" 
              />
              <div style={{ marginTop:5 }}>
                <input
                  ref={fileRef}
                  type="file"
                  accept="image/*"
