                        style={{ 
                          width: "100%", 
                          maxWidth:200, 
                          height:150, 
                          objectFit:"cover", 
                          borderRadius:8,
                          border:"1px solid #E5E7EB"
                        }} 
                      />
                      <div style={{ position:"absolute", top:8, right:8, display:"flex", gap:4 }}>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            onClearImage();
                          }}
                          style={{
                            background:"rgba(220, 38, 38, 0.9)",
                            color:"white",
                            border:"none",
                            borderRadius:"50%",
                            width:24,
                            height:24,
                            cursor:"pointer",
                            display:"flex",
                            alignItems:"center",
                            justifyContent:"center",
                            fontSize:12,
                            fontWeight:"bold"
                          }}
                          title="Borrar imagen"
                        >
                          ×
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            fileRef.current?.click();
                          }}
                          style={{
                            background:"rgba(59, 130, 246, 0.9)",
                            color:"white",
                            border:"none",
                            borderRadius:"50%",
                            width:24,
                            height:24,
                            cursor:"pointer",
                            display:"flex",
                            alignItems:"center",
                            justifyContent:"center",
                            fontSize:12,
                            fontWeight:"bold"
                          }}
                          title="Cambiar imagen"
                        >
                          📷
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div>
                      <div style={{ fontSize:32, marginBottom:8 }}>📷</div>
                      <div style={{ fontWeight:600, color:"#374151", marginBottom:4 }}>
                        {uploadingImage ? "Subiendo imagen..." : "Hacé clic para subir imagen"}
                      </div>
                      <div style={{ fontSize:12, color:"#9CA3AF" }}>
                        Formatos: JPG, PNG, GIF (máx. 5MB)
                      </div>
                    </div>
                  )}
                </div>
                {uploadingImage && (
                  <div style={{ 
                    marginTop:10, 
                    textAlign:"center", 
                    color:"#C41E3A", 
                    fontSize:13, 
                    fontWeight:500 
                  }}>
                    ⏳ Subiendo imagen a Supabase...
                  </div>
                )}
              </div>
            </div>
          </div>
          <div style={{ display:"flex", gap:10, marginTop:24 }}>
            <button onClick={onSubmit} className="btn-red" style={{ flex:1, padding:14, fontSize:15, borderRadius:12, justifyContent:"center" }}>
              {editing ? "💾 Guardar cambios" : "✅ Agregar producto"}
            </button>
            <button onClick={() => { setAdminTab("list"); setEditing(false); }} style={{ background:"#F4F4F5", color:"#6B7280", border:"none", borderRadius:12, padding:"14px 20px", cursor:"pointer", fontSize:14, fontFamily:"'Poppins',sans-serif" }}>
              Cancelar
            </button>
          </div>

                  </div>
      )}

      {/* TAB: PRICES */}
      {adminTab === "prices" && (
        <PriceManagement 
          products={products}
          onUpdateSinglePrice={onUpdateSinglePrice}
          onUpdateBulkPrices={onUpdateBulkPrices}
          onPreviewBulkPriceChanges={onPreviewBulkPriceChanges}
          priceHistory={priceHistory}
        />
      )}

      {/* TAB: HISTORY */}
      {adminTab === "history" && (
        <PriceHistory priceHistory={priceHistory} />
      )}

      {/* TAB: RESTORE */}
      {adminTab === "restore" && (
        <RestorePoints 
          restorePoints={restorePoints}
          onCreateRestorePoint={onCreateRestorePoint}
          onRestoreFromPoint={onRestoreFromPoint}
          onDeleteRestorePoint={onDeleteRestorePoint}
          loadingRestorePoints={loadingRestorePoints}
