      const newPoint = {
        id: data.id,
        timestamp: data.created_at,
        reason: data.name,
        description: data.description,
        products: data.snapshot?.products || [],
        priceHistory: data.snapshot?.priceHistory || [],
        user: data.snapshot?.user || 'unknown'
      };

