            onDrop={e => { e.preventDefault(); const f = e.dataTransfer.files[0]; if(f && fileRef.current){ fileRef.current.files = e.dataTransfer.files; fileRef.current.dispatchEvent(new Event("change",{bubbles:true})); } }}>
