import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // Actualizar el estado para que el siguiente renderizado muestre la UI alternativa
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // Registrar el error en la consola para debugging
    console.error('ErrorBoundary atrapó un error:', error, errorInfo);

    // Guardar información del error para mostrarla
    this.setState({
      error: error,
      errorInfo: errorInfo
    });
  }

  render() {
    if (this.state.hasError) {
      // Renderizado de fallback elegante
      return (
        <div style={{
          minHeight: '100vh',
          background: '#F4F4F5',
          fontFamily: "'Poppins', sans-serif",
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '20px'
        }}>
          <div style={{
            textAlign: 'center',
            background: 'white',
            borderRadius: '16px',
            padding: '40px',
            boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
            maxWidth: '500px',
            width: '100%'
          }}>
            <div style={{ fontSize: '64px', marginBottom: '20px' }}>⚠️</div>
            <h2 style={{ 
              margin: '0 0 16px', 
              color: '#111', 
              fontSize: '24px',
              fontWeight: '800'
            }}>
              Algo salió mal
            </h2>
            <p style={{ 
              margin: '0 0 24px', 
              color: '#6B7280', 
              fontSize: '16px',
              lineHeight: '1.5'
            }}>
              Star Family encontró un error inesperado. Por favor, recarga la página.
            </p>
            <button
              onClick={() => window.location.reload()}
              style={{
                background: '#C41E3A',
                color: 'white',
                border: 'none',
                borderRadius: '10px',
                padding: '12px 24px',
                fontSize: '16px',
                fontWeight: '600',
                cursor: 'pointer',
                transition: 'background 0.2s'
              }}
              onMouseOver={(e) => e.target.style.background = '#A01731'}
              onMouseOut={(e) => e.target.style.background = '#C41E3A'}
            >
              Recargar página
            </button>

            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details style={{ 
                marginTop: '24px', 
                textAlign: 'left',
                background: '#F9FAFB',
                border: '1px solid #E5E7EB',
                borderRadius: '8px',
                padding: '16px'
              }}>
                <summary style={{ 
                  cursor: 'pointer', 
                  fontWeight: '600',
                  color: '#374151',
                  marginBottom: '8px'
                }}>
                  Detalles del error (desarrollo)
                </summary>
                <pre style={{ 
                  margin: 0,
                  fontSize: '12px',
                  color: '#DC2626',
                  whiteSpace: 'pre-wrap',
                  wordBreak: 'break-word'
                }}>
                  {this.state.error && this.state.error.toString()}
                  <br />
                  <br />
                  {this.state.errorInfo.componentStack}
                </pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    // Renderizar normalmente si no hay errores
    return this.props.children;
  }
}

export default ErrorBoundary;

src/MasterProtectedRoute.jsx.content:
// ═════════════════════════════════════════════════════
// COMPONENTE DE RUTA PROTEGIDA PARA USUARIOS MAESTROS
// ═════════════════════════════════════════════════════

import React from 'react';
import { useMasterUser } from './useMasterUser';

export const MasterProtectedRoute = ({ children, fallback = null }) => {
  const { isMaster, loading, user } = useMasterUser();

  // Mientras carga, mostrar spinner o nada
  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[200px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  // Si no hay usuario autenticado
  if (!user) {
    return fallback || (
      <div className="flex flex-col items-center justify-center min-h-[200px] p-8 text-center">
        <div className="text-red-500 text-6xl mb-4">🔒</div>
        <h3 className="text-xl font-semibold text-gray-800 mb-2">
          Acceso Restringido
        </h3>
        <p className="text-gray-600 mb-4">
          Debes iniciar sesión para acceder a esta función
        </p>
      </div>
    );
  }

  // Si el usuario no es master
  if (!isMaster) {
    return fallback || (
      <div className="flex flex-col items-center justify-center min-h-[200px] p-8 text-center">
        <div className="text-red-500 text-6xl mb-4">🚫</div>
        <h3 className="text-xl font-semibold text-gray-800 mb-2">
          Acceso Denegado
        </h3>
        <p className="text-gray-600 mb-4">
          Esta función está disponible solo para usuarios maestros
        </p>
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mt-4">
          <p className="text-sm text-yellow-800">
            <strong>Nota:</strong> Si crees que deberías tener acceso, contacta al administrador del sistema.
          </p>
        </div>
      </div>
    );
  }

  // Usuario es master, permitir acceso
  return children;
};

// Hook para verificar permisos en componentes
export const useMasterPermission = () => {
  const { isMaster, loading, user } = useMasterUser();

  const checkPermission = () => {
    if (loading) return { allowed: false, reason: 'loading' };
    if (!user) return { allowed: false, reason: 'not_authenticated' };
    if (!isMaster) return { allowed: false, reason: 'not_master' };
    return { allowed: true, reason: 'authorized' };
  };

  return {
    isMaster,
    loading,
    user,
    checkPermission,
    canAccess: checkPermission().allowed,
    reason: checkPermission().reason
  };
};

// Componente para botón/menú protegido
export const MasterProtectedButton = ({ 
  children, 
  onClick, 
  disabled = false, 
  className = '',
  ...props 
}) => {
  const { isMaster, loading, user } = useMasterUser();

  const handleClick = (e) => {
    if (!user) {
      alert('Debes iniciar sesión para realizar esta acción');
      return;
    }

    if (!isMaster) {
      alert('No tienes permisos para realizar esta acción. Solo usuarios maestros pueden acceder.');
      return;
    }

    if (onClick) onClick(e);
  };

  const isDisabled = disabled || loading || (!user) || (!isMaster);

  return (
    <button
      onClick={handleClick}
      disabled={isDisabled}
      className={`${className} ${isDisabled ? 'opacity-50 cursor-not-allowed' : ''}`}
      title={
        !user ? 'Debes iniciar sesión' :
        !isMaster ? 'Solo usuarios maestros pueden acceder' :
        props.title
      }
      {...props}
    >
      {children}
    </button>
  );
};

// Componente de enlace/menú protegido
export const MasterProtectedLink = ({ 
  children, 
  href, 
  className = '',
  onClick,
  ...props 
}) => {
  const { isMaster, loading, user } = useMasterUser();

  const handleClick = (e) => {
    if (!user) {
      e.preventDefault();
      alert('Debes iniciar sesión para acceder a esta sección');
      return;
    }

    if (!isMaster) {
      e.preventDefault();
      alert('No tienes permisos para acceder a esta sección. Solo usuarios maestros pueden acceder.');
      return;
    }

    if (onClick) onClick(e);
  };

  const isDisabled = loading || (!user) || (!isMaster);

  return (
    <a
      href={href}
      onClick={handleClick}
      className={`${className} ${isDisabled ? 'opacity-50 cursor-not-allowed pointer-events-none' : ''}`}
      {...props}
    >
      {children}
    </a>
  );
};

export default MasterProtectedRoute;

